// function sumArray(arr) mein array do
// Agar array nahi hai ya empty hai: "Invalid array"
// Agar koi non-number element hai: "Array must contain only numbers"
// Warna sum return karo

solution:
function sumArray(arr) {
  if (!Array.isArray(arr) || arr.length === 0) return "Invalid array"
  if (arr.some(item => typeof item !== "number" || Number.isNaN(item))) return "Array must contain only numbers"
  return arr.reduce((acc, n) => acc + n, 0)
}
